package app

import app.repositories.CustomerRepository
import app.repositories.OrderRepository
import app.repositories.MongoCustomerRepository
import app.repositories.MongoOrderRepository

/** The repositories over one Db, and its transaction. */
class MongoUnitOfWork(val db: Db) : UnitOfWork {
    override val orders: OrderRepository = MongoOrderRepository(db)
    override val customers: CustomerRepository = MongoCustomerRepository(db)

    /** Every write is committed at once: this only groups the code. */
    override fun <T> transaction(work: (UnitOfWork) -> T): T = work(this)
}

