package app.entities

import java.math.BigDecimal
import org.bson.types.ObjectId

/** A document of the "orders" collection; a property stays null until it is set or read. */
class Order(
    var id: String? = null,
    var number: Long? = null,
    var customer: String? = null,
    var seller: String? = null,
    var lines: List<Order.Line>? = null,
) {
    /** Gives an identifier to the documents of its lists that have none: MongoDB numbers only whole documents. */
    fun identifyItems() {
        lines?.forEach { it.id = it.id ?: ObjectId().toHexString() }
    }

    /** A nested document: it is stored with the one that holds it. */
    data class Line(
        var id: String? = null,
        var product: Order.Line.Product? = null,
        var quantity: Long? = null,
        var note: String? = null,
    ) {
        /** A nested document: it is stored with the one that holds it. */
        data class Product(
            var sku: String? = null,
            var price: BigDecimal? = null,
        )
    }
}

