        return db.find(collection, Document("_id", ObjectId(id)), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Order> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun listByCustomer(customer: String): List<Order> {
        if (!ObjectId.isValid(customer)) return emptyList()
        return db.find(collection, Document("customer", ObjectId(customer)), sort = Document("_id", 1)).map { loaded(it) }
    }

    override fun insert(entity: Order): Order {
        entity.id = entity.id ?: ObjectId().toHexString()
        entity.identifyItems()
        db.insert("Order", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Order): Order {
        entity.identifyItems()
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Order", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Order): Unit {
        db.delete("Order", collection, Document("_id", ObjectId(entity.id!!)))
    }

    override fun addLine(id: String, line: Order.Line): Order? {
        if (!ObjectId.isValid(id)) return null
        line.id = line.id ?: ObjectId().toHexString()
        val change = Document("\$push", Document("lines", lineToDocument(line)))
        return db.change("Order", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun removeLine(id: String, lineId: String): Order? {
        if (!ObjectId.isValid(id)) return null
        if (!ObjectId.isValid(lineId)) return null
        val change = Document("\$pull", Document("lines", Document("_id", ObjectId(lineId))))
        return db.change("Order", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Order {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Order: what is null is left out. */
    private fun toDocument(value: Order): Document {
