        value.id?.let { document["_id"] = ObjectId(it) }
        value.number?.let { document["number"] = it }
        value.customer?.let { document["customer"] = ObjectId(it) }
        value.seller?.let { document["seller"] = ObjectId(it) }
        value.lines?.let { held -> document["lines"] = held.map { lineToDocument(it) } }
        return document
    }

    private fun fromDocument(document: Document): Order =
        Order(
            id = document["_id"]?.toString(),
            number = (document["number"] as Number?)?.toLong(),
            customer = document["customer"]?.toString(),
            seller = document["seller"]?.toString(),
            lines = (document["lines"] as List<*>?)?.mapNotNull { (it as Document?)?.let { lineFromDocument(it) } },
        )

    /** The document of a Order.Line: what is null is left out. */
