        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.product?.let { document["product"] = lineProductToDocument(it) }
        value.quantity?.let { document["quantity"] = it }
        value.note?.let { document["note"] = it }
        return document
    }

    private fun lineFromDocument(document: Document): Order.Line =
        Order.Line(
            id = document["_id"]?.toString(),
            product = (document["product"] as Document?)?.let { lineProductFromDocument(it) },
            quantity = (document["quantity"] as Number?)?.toLong(),
            note = document["note"] as String?,
        )

    /** The document of a Order.Line.Product: what is null is left out. */
    private fun lineProductToDocument(value: Order.Line.Product): Document {
        val document = Document()
        value.sku?.let { document["sku"] = it }
        value.price?.let { document["price"] = Decimal128(it) }
        return document
    }

    private fun lineProductFromDocument(document: Document): Order.Line.Product =
        Order.Line.Product(
            sku = document["sku"] as String?,
            price = Documents.decimal(document["price"]),
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Order, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

