package app.services

import app.UnitOfWork
import app.common.Page
import app.entities.Customer
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException
import java.math.BigDecimal
import java.time.Instant
import java.util.UUID

/** Operations on customers. Repositories commit every write. */
@Suppress("UNCHECKED_CAST")
class CustomerService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Customer after checking it. */
    fun createCustomer(customer: Customer): Customer {
        val values = mapOf(
            "email" to customer.email,
            "name" to customer.name,
            "age" to customer.age,
            "balance" to customer.balance,
            "visits" to customer.visits,
            "rate" to customer.rate,
            "active" to customer.active,
            "address" to customer.address,
            "tags" to customer.tags,
            "seen" to customer.seen,
            "ref" to customer.ref,
            "photo" to customer.photo,
            "scores" to customer.scores,
            "mixed" to customer.mixed,
            "nothing" to customer.nothing,
            "empty" to customer.empty,
            "deletedAt" to customer.deletedAt,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.customers.insert(customer)
        }
    }

    /** The Customer with this key; NotFoundException when there is none. */
    fun getCustomer(id: String): Customer = find(unitOfWork, id)

    /** A page of customers, by primary key. */
    fun listCustomers(offset: Int, limit: Int): Page<Customer> = unitOfWork.customers.list(offset, limit)

    /** Changes the given values of a Customer. */
    fun updateCustomer(id: String, changes: CustomerChanges): Customer {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.customers.update(current)
        }
    }

    /** Marks a Customer as deleted (deletedAt); reads leave it out from then on. */
    fun deleteCustomer(id: String) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (uow.orders.listByCustomer(current.id!!).isNotEmpty())
                throw ConflictException("Customer", "rows of orders still point to it", listOf("orders"))
            current.deletedAt = Instant.now()
            uow.customers.update(current)
        }
    }

    /** Adds an item to tags. */
    fun addTag(id: String, tag: String): Customer {
        return unitOfWork.transaction { uow ->
            find(uow, id)
            uow.customers.addTag(id, tag) ?: throw NotFoundException("Customer", id)
        }
    }

    /** Removes an item from tags, by its value. */
    fun removeTag(id: String, tag: String): Customer {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (tag !in current.tags.orEmpty()) throw NotFoundException("Tag", tag)
            uow.customers.removeTag(id, tag) ?: throw NotFoundException("Customer", id)
        }
    }

    /** Adds an item to empty. */
    fun addEmpty(id: String, empty: Any): Customer {
        return unitOfWork.transaction { uow ->
            find(uow, id)
            uow.customers.addEmpty(id, empty) ?: throw NotFoundException("Customer", id)
        }
    }

    /** Removes an item from empty, by its position. */
    fun removeEmpty(id: String, position: Int): Customer {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (position !in current.empty.orEmpty().indices) throw NotFoundException("Empty", position)
            uow.customers.removeEmpty(id, position, current.empty.orEmpty().size) ?: throw ConflictException("Customer", "was changed by someone else since it was read", listOf("empty"))
        }
    }

    /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["email"]
            if (value == null) {
                if (creating || "email" in values) errors += FieldError("email", "is required")
            }
        }
        run {
            val value = values["name"]
            if (value == null) {
                if (creating || "name" in values) errors += FieldError("name", "is required")
            }
        }
        run {
            val value = values["rate"]
            if (value == null) {
                if (creating || "rate" in values) errors += FieldError("rate", "is required")
            }
        }
        run {
            val value = values["active"]
            if (value == null) {
                if (creating || "active" in values) errors += FieldError("active", "is required")
            }
        }
        run {
            val value = values["address"]
            if (value == null) {
                if (creating || "address" in values) errors += FieldError("address", "is required")
            } else {
                val document = value as Customer.Address
                checkAddress(document, "address", errors)
            }
        }
        run {
            val value = values["tags"]
            if (value == null) {
                if (creating || "tags" in values) errors += FieldError("tags", "is required")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Customer", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Customer, values: Map<String, Any?>) {
        if ("email" in values) entity.email = values["email"] as String?
        if ("name" in values) entity.name = values["name"] as String?
        if ("age" in values) entity.age = values["age"] as Long?
        if ("balance" in values) entity.balance = values["balance"] as BigDecimal?
        if ("visits" in values) entity.visits = values["visits"] as Long?
        if ("rate" in values) entity.rate = values["rate"] as Double?
        if ("active" in values) entity.active = values["active"] as Boolean?
        if ("address" in values) entity.address = values["address"] as Customer.Address?
        if ("tags" in values) entity.tags = values["tags"] as List<String>?
        if ("seen" in values) entity.seen = values["seen"] as Instant?
        if ("ref" in values) entity.ref = values["ref"] as UUID?
        if ("photo" in values) entity.photo = values["photo"] as ByteArray?
        if ("scores" in values) entity.scores = values["scores"] as Any?
        if ("mixed" in values) entity.mixed = values["mixed"] as Any?
        if ("nothing" in values) entity.nothing = values["nothing"] as Any?
        if ("empty" in values) entity.empty = values["empty"] as List<Any>?
        if ("deletedAt" in values) entity.deletedAt = values["deletedAt"] as Instant?
    }

    /** The Customer with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: String): Customer =
        uow.customers.findById(id) ?: throw NotFoundException("Customer", id)

    /** The values an update gives, by field. */
    private fun given(changes: CustomerChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.email.isPresent) values["email"] = changes.email.value
        if (changes.name.isPresent) values["name"] = changes.name.value
        if (changes.age.isPresent) values["age"] = changes.age.value
        if (changes.balance.isPresent) values["balance"] = changes.balance.value
        if (changes.visits.isPresent) values["visits"] = changes.visits.value
        if (changes.rate.isPresent) values["rate"] = changes.rate.value
        if (changes.active.isPresent) values["active"] = changes.active.value
        if (changes.address.isPresent) values["address"] = changes.address.value
        if (changes.tags.isPresent) values["tags"] = changes.tags.value
        if (changes.seen.isPresent) values["seen"] = changes.seen.value
        if (changes.ref.isPresent) values["ref"] = changes.ref.value
        if (changes.photo.isPresent) values["photo"] = changes.photo.value
        if (changes.scores.isPresent) values["scores"] = changes.scores.value
        if (changes.mixed.isPresent) values["mixed"] = changes.mixed.value
        if (changes.nothing.isPresent) values["nothing"] = changes.nothing.value
        if (changes.empty.isPresent) values["empty"] = changes.empty.value
        if (changes.deletedAt.isPresent) values["deletedAt"] = changes.deletedAt.value
        return values
    }

    /** What a Customer.Address does not follow of its rules, each with the path of its field. */
    private fun checkAddress(value: Customer.Address, path: String, errors: MutableList<FieldError>) {
        if (value.street == null) errors += FieldError(path + ".street", "is required")
        if (value.city == null) errors += FieldError(path + ".city", "is required")
    }
