        assertEquals(2L, page.total)
        assertEquals(1, page.items.size)
    }

    @Test
    fun storesTheChanges() {
        val stored = Factories.addCustomer(uow, 1)
        stored.email = "changed"
        uow.customers.update(stored)
        assertEquals("changed", uow.customers.findById(stored.id!!)?.email)
    }

    @Test
    fun addsAndRemovesOneItemOfTags() {
        val n = 7
        val stored = Factories.addCustomer(uow, 1)
