        val item: String = "tags-$n"
        val added = uow.customers.addTag(stored.id!!, item)!!
        assertEquals(before + 1, added.tags.orEmpty().size)
        val removed = uow.customers.removeTag(stored.id!!, item)!!
        assertEquals(before, removed.tags.orEmpty().size)
    }

    @Test
    fun addsAndRemovesOneItemOfEmpty() {
        val n = 7
        val stored = Factories.addCustomer(uow, 1)
        val before = stored.empty.orEmpty().size
        val item: Any = mapOf("n" to n)
        val added = uow.customers.addEmpty(stored.id!!, item)!!
        assertEquals(before + 1, added.empty.orEmpty().size)
        val removed = uow.customers.removeEmpty(stored.id!!, before, added.empty.orEmpty().size)!!
        assertEquals(before, removed.empty.orEmpty().size)
        assertNull(uow.customers.removeEmpty(stored.id!!, 0, before + 5))
    }
}

